    public List<Double> averageOfLevels(TreeNode root) {
        List<List<Integer>> levels = new ArrayList<>();
        dfs(root, 0, levels);
        List<Double> ans = new ArrayList<>();
        for (List<Integer> lvl : levels) {
            double sum = 0;
            for (int v : lvl) sum += v;
            ans.add(sum / lvl.size());
        }
        return ans;
    }
    private void dfs(TreeNode node, int lvl, List<List<Integer>> levels) {
        if (node == null) return;
        if (lvl == levels.size()) levels.add(new ArrayList<>());
        levels.get(lvl).add(node.val);
        dfs(node.left, lvl + 1, levels);
        dfs(node.right, lvl + 1, levels);
    }
}

