class Solution {
    public TreeNode mergeTrees(TreeNode root1, TreeNode root2) {
        if (root1 == null) return root2;
        if (root2 == null) return root1;
        TreeNode root = new TreeNode(root1.val + root2.val);
        Queue<TreeNode[]> q = new LinkedList<>();
        q.offer(new TreeNode[]{root, root1, root2});
        while (!q.isEmpty()) {
            TreeNode[] cur = q.poll();
            TreeNode node = cur[0], n1 = cur[1], n2 = cur[2];
            if (n1.left != null || n2.left != null) {
                if (n1.left != null && n2.left != null) {
                    node.left = new TreeNode(n1.left.val + n2.left.val);
                    q.offer(new TreeNode[]{node.left, n1.left, n2.left});
                } else if (n1.left != null) {
                    node.left = n1.left;
                } else {
                    node.left = n2.left;
                }
            }
            if (n1.right != null || n2.right != null) {
                if (n1.right != null && n2.right != null) {
                    node.right = new TreeNode(n1.right.val + n2.right.val);
                    q.offer(new TreeNode[]{node.right, n1.right, n2.right});
                } else if (n1.right != null) {
                    node.right = n1.right;
                } else {
                    node.right = n2.right;
                }
            }
        }
        return root;
    }
}

