        if (node == null) return 0;
        String key = node.val + "," + lookup(node.left) + "," + lookup(node.right);
        int id = idMap.computeIfAbsent(key, k -> nextId++);
        countMap.put(id, countMap.getOrDefault(id, 0) + 1);
        if (countMap.get(id) == 2) {
            duplicates.add(node);
        }
        return id;
    }
