    public List<List<Integer>> verticalTraversal(TreeNode root) {
        List<Point> points = new ArrayList<>();
        dfs(root, 0, 0, points);
        points.sort((a, b) -> {
            if (a.col != b.col) return a.col - b.col;
            if (a.row != b.row) return a.row - b.row;
            return a.val - b.val;
        });
        List<List<Integer>> res = new ArrayList<>();
        int prevCol = Integer.MIN_VALUE;
        for (Point p : points) {
            if (p.col != prevCol) {
                res.add(new ArrayList<>());
                prevCol = p.col;
            }
            res.get(res.size() - 1).add(p.val);
        }
        return res;
    }
    private void dfs(TreeNode node, int c, int r, List<Point> points) {
        if (node == null) return;
        points.add(new Point(c, r, node.val));
        dfs(node.left, c - 1, r + 1, points);
        dfs(node.right, c + 1, r + 1, points);
    }
}

