class Solution {
    public TreeNode trimBST(TreeNode root, int low, int high) {
        List<Integer> list = new ArrayList<>();
        collect(root, low, high, list);
        return build(list, 0, list.size() - 1);
    }
    private void collect(TreeNode node, int low, int high, List<Integer> list) {
        if (node == null) return;
        collect(node.left, low, high, list);
        if (node.val >= low && node.val <= high) list.add(node.val);
        collect(node.right, low, high, list);
    }
    private TreeNode build(List<Integer> list, int l, int r) {
        if (l > r) return null;
        int m = l + (r - l) / 2;
        TreeNode node = new TreeNode(list.get(m));
        node.left = build(list, l, m - 1);
        node.right = build(list, m + 1, r);
        return node;
    }
}

